  function fallbackCopy(text) {
    var ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    var ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta); return ok;
  }

  document.querySelectorAll('.card').forEach(function (card) {
    var svg = card.querySelector('.stage svg');
    if (!svg) return;
    var name = (card.querySelector('.name') || {}).textContent || 'asset';

    // Replay control on the stage — re-runs the asset's animation for inspection.
    var stage = card.querySelector('.stage');
    if (stage) {
      var replay = document.createElement('button');
      replay.type = 'button';
      replay.className = 'replay-btn';
      replay.innerHTML = REPLAY_IC + '<span>Replay</span>';
